// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint _am, uint _initialBalance, uint _unlockTime) public {
        // Constrain parameters: _am must be <= _initialBalance and both > 0, and _unlockTime in the past
        vm.assume(_initialBalance > 0 && _initialBalance <= 100 ether);
        vm.assume(_am > 0 && _am <= _initialBalance);
        vm.assume(_unlockTime < block.timestamp);

        // Fund the test contract to call Put with a specific msg.value
        vm.deal(address(this), _initialBalance);
        // Put: send _initialBalance to c, unlock time in the past
        c.Put{value: _initialBalance}(_unlockTime);
        // Now Collect: msg.sender = this, amount = _am
        uint balanceBeforeCollect = address(c).balance;
        c.Collect(_am);
        // General rule: after Collect, contract balance = balanceBeforeCollect - _am
        assertTrue(address(c).balance == balanceBeforeCollect - _am, "Contract balance after Collect should decrease by _am");
    }
}

