pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 balance, uint256 unlockTime, uint256 amount) public {
        // Constrain inputs
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(balance > 0 && amount > 0);
        // Set caller's balance in the contract
        vm.deal(caller, balance);
        vm.prank(caller);
        c.Put{value: balance}(unlockTime);
        // Ensure caller has at least 1 ether and time has passed
        vm.warp(unlockTime + 1);
        // Get caller's balance before Collect
        (uint256 balBefore, ) = c.Acc(caller);
        // Call Collect with amount, which may revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
        // Get caller's balance after Collect
        (uint256 balAfter, ) = c.Acc(caller);
        // General rule: if Collect reverted, balance must be unchanged
        if (!success) {
            assertTrue(balBefore == balAfter);
        } else {
            // If succeeded, balance decreased by amount (skip assertion, not needed)
            assertTrue(balBefore >= balAfter);
        }
    }
}

