pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 unlockTime, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        unlockTime = bound(unlockTime, 0, type(uint256).max - 100);
        depositAmount = bound(depositAmount, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // Deal ether to caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put{value: depositAmount}(unlockTime);

        // Get initial state
        uint256 callerBalanceBefore = c.Acc(caller).balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Try to collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Get final state
        uint256 callerBalanceAfter = c.Acc(caller).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: balance change equals collectAmount if success, else 0
        if (success) {
            assertTrue(callerBalanceAfter == callerBalanceBefore - collectAmount, "Balance should decrease by collectAmount on success");
        } else {
            assertTrue(callerBalanceAfter == callerBalanceBefore, "Balance should remain same on revert");
        }

        // Contract balance consistency: total = sum of all balances + initial (0)
        // Since we only track caller's balance and contract balance, we check that
        // contract balance change equals the net ether transfer
        if (success) {
            assertTrue(contractBalanceAfter == contractBalanceBefore - collectAmount, "Contract balance should decrease by collectAmount");
        } else {
            assertTrue(contractBalanceAfter == contractBalanceBefore, "Contract balance should not change on revert");
        }
    }
}

