pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am, uint256 deposit) public {
        // Ensure deposit is enough to meet MinSum and cover am
        vm.assume(deposit >= 1 ether && am <= deposit && am > 0);

        // Fund the test contract and send value to Put
        vm.deal(address(this), deposit);
        vm.prank(address(this));
        c.Put{value: deposit}(block.timestamp);

        // Advance time beyond unlockTime
        vm.warp(block.timestamp + 1);

        // Now call Collect; may revert if insufficient balance or time
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: if Collect did not revert, then another nonReentrant_ call should succeed
        bool secondReverted;
        try c.Collect(am) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assertTrue(!reverted || !secondReverted); // actually we want: if first succeeds, second must succeed
        // More precisely: if first didn't revert, second should not revert
        if (!reverted) {
            assertTrue(!secondReverted);
        } else {
            assertTrue(true); // rule holds trivially when first reverts
        }
    }
}

